package com.atskolla.teacher;
import android.app.*;import android.os.*;import android.widget.*;import org.json.*;import java.util.*;import java.io.*;import static com.atskolla.teacher.Json.*;
/** All writes and notification deliveries use FixtureApi; no production side effects. */
public final class TeacherChecksActivity extends Activity {
 void require(boolean b,String m){if(!b)throw new AssertionError(m);}
 @Override public void onCreate(Bundle state){super.onCreate(state);TextView label=new TextView(this);label.setText("TEACHER CHECKING");setContentView(label);new Thread(()->{try{
  FixtureApi api=new FixtureApi(this);TeacherStore store=new TeacherStore(api);store.initialize();require(store.waliClasses().equals(Collections.singletonList("VII A")),"Wrong assignments");require(store.leaves().length()==1,"Foreign leave exposed");
  Map<String,String> statuses=new LinkedHashMap<>();statuses.put("student-1","hadir");statuses.put("student-2","sakit");store.saveSubject(api.schedule(),api.pupils(),statuses,"Latihan kelompok");JSONObject write=api.writes.get(0);require(s(write,"table").equals("subject_attendance")&&write.optBoolean("upsert"),"Subject upsert missing");require(android.net.Uri.decode(s(write,"query")).contains("student_id,teaching_schedule_id,date"),"Wrong conflict key");require(s(first(a(write,"body")),"teacher_id").equals(FixtureApi.UID),"Teacher identity lost");
  boolean rejected=false;try{store.saveSubject(j("id","foreign-schedule"),api.pupils(),statuses,"");}catch(IOException e){rejected=true;}require(rejected,"Foreign schedule accepted");rejected=false;try{store.students("VIII B");}catch(IOException e){rejected=true;}require(rejected,"Foreign class accepted");
  api.holiday=true;rejected=false;try{store.saveSubject(api.schedule(),api.pupils(),statuses,"");}catch(IOException e){rejected=true;}require(rejected,"Holiday save accepted");api.holiday=false;
  Map<String,String> change=new LinkedHashMap<>();change.put("student-1","izin");api.writes.clear();store.saveManual("VII A",store.today().toString(),api.pupils(),change,api.get("attendance_logs",""));require(api.writes.size()==1,"Unexpected manual write");JSONObject manual=api.writes.get(0);require(s(manual,"method").equals("PATCH")&&android.net.Uri.decode(s(manual,"query")).contains("attendance_type=eq.datang"),"Manual edit overwrote departures");
  api.writes.clear();store.review(first(store.leaves()),"approved","Semoga lekas pulih");require(api.writes.size()==2,"Leave sync missing");for(JSONObject row:api.writes)require(!s(row,"method").equals("DELETE"),"Leave deleted departure history");
  api.suspended=true;rejected=false;try{store.initialize();}catch(IOException e){rejected=true;}require(rejected,"Suspended school allowed");api.suspended=false;
  TeacherApi persistent=new TeacherApi(this);persistent.store(j("access_token","synthetic-only","refresh_token","synthetic-refresh","user",j("id",FixtureApi.UID)));require(new TeacherApi(this).uid().equals(FixtureApi.UID),"Encrypted session restoration failed");persistent.localLogout();
  List<JSONObject> pupils=Json.list(api.pupils()),logs=Json.list(api.get("attendance_logs",""));require(ReportFiles.counts("student-1",logs)[0]==1,"Report count incorrect");byte[] pdf=ReportFiles.pdf("Sekolah Contoh", "Ibu Ratna", "Laporan Kelas VII A",store.today().withDayOfMonth(1).toString(),store.today().toString(),pupils,logs);byte[] excel=ReportFiles.xlsx("Sekolah Contoh","Rekap VII A",store.today().withDayOfMonth(1).toString(),store.today().toString(),pupils,logs);try(FileOutputStream out=openFileOutput("teacher-report.pdf",MODE_PRIVATE)){out.write(pdf);}try(FileOutputStream out=openFileOutput("teacher-report.xlsx",MODE_PRIVATE)){out.write(excel);}require(pdf.length>1000&&excel.length>1000,"Export too small");require(pdf[0]=='%'&&excel[0]=='P'&&excel[1]=='K',"Invalid file formats");
  runOnUiThread(()->label.setText("TEACHER CHECKS PASSED"));
 }catch(Throwable e){runOnUiThread(()->label.setText("TEACHER CHECKS FAILED: "+e));}}).start();}
}
